const rawText = $input.item.json.text;

const cleaned = rawText
  .replace(/^```json\n?/, '')
  .replace(/^```\n?/, '')
  .replace(/```$/, '')
  .trim();

let inString = false;
let escaped = false;
let result = '';
for (let i = 0; i < cleaned.length; i++) {
  const ch = cleaned[i];
  if (escaped) { result += ch; escaped = false; }
  else if (ch === '\\') { result += ch; escaped = true; }
  else if (ch === '"') { result += ch; inString = !inString; }
  else if (inString && ch === '\n') { result += '\\n'; }
  else if (inString && ch === '\r') { result += '\\r'; }
  else if (inString && ch === '\t') { result += '\\t'; }
  else { result += ch; }
}

const normalized = result
  .replace(/\u2018/g, "'").replace(/\u2019/g, "'")
  .replace(/\u201C/g, '\\"').replace(/\u201D/g, '\\"');

let depth = 0, jsonEnd = -1, inStr = false, esc = false;
const firstChar = normalized.trimStart()[0];
const opener = firstChar === '[' ? '[' : '{';
const closer = firstChar === '[' ? ']' : '}';
for (let i = 0; i < normalized.length; i++) {
  const c = normalized[i];
  if (esc) { esc = false; continue; }
  if (c === '\\') { esc = true; continue; }
  if (c === '"') { inStr = !inStr; continue; }
  if (!inStr) {
    if (c === opener) depth++;
    else if (c === closer) { depth--; if (depth === 0) { jsonEnd = i; break; } }
  }
}

if (jsonEnd === -1) throw new Error('No s\'ha trobat JSON vàlid. Text: ' + cleaned.substring(0, 300));

let parsed;
try {
  parsed = JSON.parse(normalized.substring(0, jsonEnd + 1));
} catch(e) {
  throw new Error('Error parsejant JSON: ' + e.message + '\nText: ' + normalized.substring(0, 500));
}

if (parsed.error) throw new Error('Gemini ha reportat un error: ' + parsed.error);

return [{ json: parsed }];

const item = $input.item.json;

// Funció per llegir un camp que pot venir com a nom real o com a Columna X
const get = (realName, colName) => item[realName] ?? item[colName] ?? '';

// Ignorar files buides
const pdf = get('Enunciat del projecte (PDF)', 'Columna 2');
const membres = get('Noms dels membres (separats per comes)', 'Columna 4');
if (!pdf && !membres) return [];

return [{
  json: {
    'Enunciat del projecte (PDF)':                  pdf,
    'Hores totals de classe per al projecte':       get('Hores totals de classe per al projecte', 'Columna 3'),
    'Noms dels membres (separats per comes)':       membres,
    'Número de grup':                               get('Número de grup', 'Columna 5'),
    'Informació adicional i peticions per a la IA': get('Informació adicional i peticions per a la IA', 'Columna 6'),
    'Nom carpeta del projecte':                     get('Nom carpeta del projecte', 'Columna 8'),
    'Assignació de rols del grup':                  get('Assignació de rols del grup', 'Columna 9'),
    'Adreces de contacte dels membres':             get('Adreces de contacte dels membres', 'Columna 10'),
    'Nom i codi del mòdul':                         get('Nom i codi del mòdul', 'Columna 11'),
  }
}];

const item = $input.item.json;

const grup      = item['Número de grup'] ?? '';
const membres   = item['Noms dels membres (separats per comes)'] ?? '';
const rols      = (item['Assignació de rols del grup'] ?? '').replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
const contactes = item['Adreces de contacte dels membres'] ?? '';
const modul     = item['Nom i codi del mòdul'] ?? '';
const hores     = String(item['Hores totals de classe per al projecte'] ?? '');
const extra     = item['Informació adicional i peticions per a la IA'] ?? '';

const pdfText = (item['text'] ?? '').trim();

const pdfStatus = pdfText.length > 200
  ? `TEXT COMPLET DEL PDF DE L'ENUNCIAT:\n=== INICI PDF ===\n${pdfText}\n=== FI PDF ===`
  : `ERROR CRÍTIC: PDF buit (${pdfText.length} cars). Retorna exactament: {"error":"PDF no llegible"}`;

const prompt = `NOVA TASCA INDEPENDENT — IGNORA QUALSEVOL CONTEXT ANTERIOR.
DADES DEL FORMULARI (copia aquests valors EXACTAMENT):
- Grup: ${grup}
- Membres: ${membres}
- Rols del grup: ${rols}
- Contactes: ${contactes}
- Mòdul (nom_modul = EXACTAMENT aquest text): ${modul}
- Hores totals (hores_totals = EXACTAMENT aquest número): ${hores}
- Informació addicional (acord_altres = EXACTAMENT aquest text, o buit si no hi ha res): ${extra || ''}
${pdfStatus}
RECORDATORI FINAL OBLIGATORI — CAMPS QUE HAN DE TENIR VALOR:
- grup = "${grup}" (NO deixis buit)
- membres = "${membres}" (NO deixis buit)
- nom_modul = "${modul}" (NO deixis buit)
- hores_per_alumne = "${hores}" (NO deixis buit)
- hores_totals = calcula: ${hores} multiplicat pel nombre de membres
- acord_contactes = "${contactes}" (copia LITERAL, NO deixis buit)
- acord_frequencia_wiki, acord_frequencia_correu, acord_antelacio_reunio, acord_marge_resposta, acord_colors = inventa valors raonables en català (NO deixis buit)
- acord_altres = "${extra || ''}"
- totes les tasca_X_durada han de sumar exactament les hores_totals (NO posar 0h)`;

return { prompt, pdfLength: pdfText.length, grup, modul, hores };

const data = $input.first().json;
const gsTrigger = $('variables formulari').first().json;
const grup     = gsTrigger['Número de grup']  ?? '';
const membres  = gsTrigger['Noms dels membres (separats per comes)']  ?? '';
const nomModul = gsTrigger['Nom i codi del mòdul'] ?? '';


const obj = data.objectius   ?? {};
const ac  = data.acords      ?? {};
const pt  = data.pla_treball ?? {};

const sd = (v) => {
  if (v == null || v === undefined) return ' ';
  const str = String(v).replace(/\r/g, '').trim();
  return str === '' ? ' ' : str;
};

const s = (v) => {
  if (v == null || v === undefined) return '';
  return String(v).replace(/\r/g, '').trim();
};

const makeReplace = (tag, replaceText) => ({
  replaceAllText: {
    containsText: { text: '[' + tag + ']', matchCase: true },
    replaceText: sd(replaceText)
  }
});

// ----- EXTREURE ROLS I CONTACTES DEL FORMULARI -----
const rols     = gsTrigger['Assignació de rols del grup'] ?? '';
const contactes = gsTrigger['Adreces de contacte dels membres'] ?? '';

const extractRol = (rolName) => {
  const regex = new RegExp(rolName + '[:\\s]+([^,\\n]+)', 'i');
  const match = rols.match(regex);
  return match ? match[1].trim() : "Pendent d'assignar";
};

const acord_coordinador   = extractRol('Coordinador');
const acord_corrector     = extractRol('Corrector');
const acord_unificador    = extractRol('Unificador');
const acord_recordador    = extractRol('Recordador');
const acord_secretari     = extractRol('Secretari');
const acord_normalitzador = extractRol('Normalitzador');
const acord_multimedia    = extractRol('Multimèdia') !== "Pendent d'assignar"
                            ? extractRol('Multimèdia')
                            : extractRol('Multimedia');
// ---------------------------------------------------

// 1. Mapeig d'Objectius
const requestsObjectius = [
  makeReplace('cicle',                 obj.cicle),
  makeReplace('curs',                  obj.curs),
  makeReplace('nom_modul',             nomModul || obj.nom_modul),
  makeReplace('resultat_aprenentatge', obj.resultat_aprenentatge),
  makeReplace('titol_activitat',       obj.titol_activitat),
  makeReplace('grup',                  grup),
  makeReplace('objectiu_1',            obj.objectiu_1),
  makeReplace('objectiu_2',            obj.objectiu_2),
  makeReplace('objectiu_3',            obj.objectiu_3),
  makeReplace('objectiu_4',            obj.objectiu_4),
  makeReplace('objectiu_5',            obj.objectiu_5),
  makeReplace('objectiu_6',            obj.objectiu_6),
];

// 2. Mapeig d'Acords
const requestsAcords = [
  makeReplace('cicle',                  ac.cicle),
  makeReplace('curs',                   ac.curs),
  makeReplace('nom_modul',              nomModul || ac.nom_modul),
  makeReplace('resultat_aprenentatge',  ac.resultat_aprenentatge),
  makeReplace('titol_activitat',        ac.titol_activitat),
  makeReplace('grup',                   grup),
  makeReplace('membres',                membres),
  makeReplace('professor',              ac.professor),
  makeReplace('acord_frequencia_wiki',  ac.acord_frequencia_wiki),
  makeReplace('acord_frequencia_correu',ac.acord_frequencia_correu),
  makeReplace('acord_antelacio_reunio', ac.acord_antelacio_reunio),
  makeReplace('acord_contactes',        contactes),
  makeReplace('acord_marge_resposta',   ac.acord_marge_resposta),
  makeReplace('acord_coordinador',      acord_coordinador),
  makeReplace('acord_corrector',        acord_corrector),
  makeReplace('acord_unificador',       acord_unificador),
  makeReplace('acord_recordador',       acord_recordador),
  makeReplace('acord_secretari',        acord_secretari),
  makeReplace('acord_normalitzador',    acord_normalitzador),
  makeReplace('acord_multimedia',       acord_multimedia),
  makeReplace('acord_colors',           ac.acord_colors),
  makeReplace('acord_altres',           ac.acord_altres),
];

// 3. Mapeig de Pla de Treball → Sheets API
const sheetName = "Full 1";

const horesPerAlumne = parseFloat(gsTrigger['Hores totals de classe per al projecte'] ?? 0);
const noms = (membres || '').split(',').filter(x => x.trim()).length || 1;
const horesTotal = horesPerAlumne * noms;

const pesos = { 'Alta': 3, 'Mitjana': 2, 'Baixa': 1 };
let pesoTotal = 0;
const taskList = [];
for (let i = 1; i <= 8; i++) {
  const nom = s(pt["tasca_" + i + "_nom"]);
  if (!nom) continue;
  const prioritat = s(pt["tasca_" + i + "_prioritat"]);
  const pes = pesos[prioritat] ?? 2;
  pesoTotal += pes;
  taskList.push({ i, pes });
}
const durades = {};
let horesAssignades = 0;
taskList.forEach((t, idx) => {
  if (idx === taskList.length - 1) {
    durades[t.i] = Math.max(0.5, Math.round((horesTotal - horesAssignades) * 2) / 2);
  } else {
    const raw = (t.pes / pesoTotal) * horesTotal;
    const arrodonit = Math.max(0.5, Math.round(raw * 2) / 2);
    durades[t.i] = arrodonit;
    horesAssignades += arrodonit;
  }
});

const sheetsPlaTraball = [
  { range: sheetName + "!C3",  values: [[s(pt.cicle)]] },
  { range: sheetName + "!G3",  values: [[s(pt.curs)]] },
  { range: sheetName + "!C4",  values: [[s(nomModul || pt.nom_modul)]] },
  { range: sheetName + "!G4", values: [[s(pt.codi_modul) ||(nomModul.match(/^\d+/)   || [''])[0]]] },
  { range: sheetName + "!C5",  values: [[s(pt.resultat_aprenentatge)]] },
  { range: sheetName + "!G5",  values: [[s(pt.professor)]] },
  { range: sheetName + "!C6",  values: [[s(grup)]] },
  { range: sheetName + "!G6",  values: [[s(membres)]] },
  { range: sheetName + "!H17", values: [[String(horesTotal)]] },
  { range: sheetName + "!H18", values: [[String(horesPerAlumne)]] },
];

const taskRows = [9, 10, 11, 12, 13, 14, 15, 16];
for (let i = 1; i <= 8; i++) {
  const row = taskRows[i - 1];
  const duradaVal = s(pt["tasca_" + i + "_nom"]) ? (durades[i] + "h") : '';
  sheetsPlaTraball.push({ range: sheetName + "!C" + row, values: [[s(pt["tasca_" + i + "_nom"])]] });
  sheetsPlaTraball.push({ range: sheetName + "!D" + row, values: [[s(pt["tasca_" + i + "_scrum"])]] });
  sheetsPlaTraball.push({ range: sheetName + "!E" + row, values: [[s(pt["tasca_" + i + "_descripcio"])]] });
  sheetsPlaTraball.push({ range: sheetName + "!F" + row, values: [[s(pt["tasca_" + i + "_resultat"])]] });
  sheetsPlaTraball.push({ range: sheetName + "!G" + row, values: [[s(pt["tasca_" + i + "_comprovacio"])]] });
  sheetsPlaTraball.push({ range: sheetName + "!H" + row, values: [[duradaVal]] });
  sheetsPlaTraball.push({ range: sheetName + "!I" + row, values: [[s(pt["tasca_" + i + "_prioritat"])]] });
}

return [{
  json: {
    ...data,
    grup,
    membres,
    nomModul,
    requests_objectius:  { requests: requestsObjectius },
    requests_acords:     { requests: requestsAcords },
    sheets_pla_treball:  sheetsPlaTraball,
  }
}];

